\section{Introduction}

\subsection{The Fermat window}
Let $N$ be a positive integer and $s=\lfloor\sqrt N\rfloor$.  Fermat's method
examines integers $j>s$ and the residues
\[
  v(j) := j^{2}-N \qquad (>0 \text{ for } j>s),
\]
seeking $j$ with $v(j)$ a perfect square, which yields
$N=(j-\sqrt{v(j)})(j+\sqrt{v(j)})$.  In modern congruence-of-squares algorithms the
perfect-square condition is relaxed: one collects positions whose residue is
$B$-smooth and combines them by linear algebra over $\mathbb F_{2}$.  The
distribution of such hits inside a scan window is therefore of direct algorithmic
interest.  We fix the \emph{window}
\[
  W(N):=\{\,j\in\mathbb Z: s<j\le 3s\,\},\qquad |W(N)|=2s,
\]
and the \emph{normalised position} $u(j):=(j-s)/(2s)\in(0,1]$.

\subsection{The empirical spike and the control that failed}
A scan across $128$ moduli of $96$ bits, with $9594$ recorded smooth hits, showed a
marked left-edge excess: the first decile $u<0.1$ carried about $8.6\%$ of the mass.
A two-component fit (broad bulk plus half-Gaussian edge component, $50$ equal-width
position bins, Poisson bin likelihood, bootstrap clustered over moduli) assigned the
edge component weight $w_{\mathrm{edge}}=0.0794$ with confidence interval
$[0.0702,0.0908]$ and a decisive margin over the bulk-only model.

Because residues at the left edge are numerically small, and small integers are far
likelier to be smooth, the natural control restricts attention to \emph{full-size}
residues $v\ge 2^{95}$ and refits.  That filter retained $7221$ of the $9594$ hits,
and the refitted weight was $w_{\mathrm{edge}}=0.0403$ with interval
$[0.0301,0.0525]$, again with a decisive margin and excluding zero.

The subject of this paper is a structural fact about the filter itself: within the
region it was meant to probe --- the first decile --- it removes everything.  This is
not a property of the sample but a theorem about parabolas.

\subsection{Results}
Throughout, $\bitlen(v)$ denotes the number of binary digits of $v$, i.e.\ the least
$b$ with $v<2^{b}$.  We prove: degeneracy of the exclusion criterion at $96$ bits
(Theorem~\ref{thm:deg96}) and its scale-free form (Theorem~\ref{thm:scalefree}); the
necessity of the size hypotheses (Proposition~\ref{prop:cex}); non-triviality of the
criterion on the tail (Theorem~\ref{thm:tail}); exact band geometry and the
deterministic histogram (Section~\ref{sec:bands}); the continuum crossing curve and
the sharp phase transition (Section~\ref{sec:cont}); sharp discrete constants
(Section~\ref{sec:sharp}); the discrete--continuum bridge (Section~\ref{sec:bridge});
and the decoupling of position from bit-length across moduli
(Section~\ref{sec:two}).

\section{Notation and basic facts}

Let $N\ge 1$ and $s=\lfloor\sqrt N\rfloor$, so $s^{2}\le N<(s+1)^{2}$.

\begin{definition}[Residue]
For $j\in\mathbb N$, $v(j)=v_{N}(j):=j^{2}-N$.  All statements below assume $j>s$,
where $v(j)>0$.
\end{definition}

\begin{definition}[Window]
$j$ lies in the window if $s<j\le 3s$.
\end{definition}

\begin{definition}[First decile]\label{def:decile}
We use the slack integer form employed in the experiment: $j$ lies in the
\emph{first decile} $D_{1}(N)$ if $s<j$ and $5(j-s)<s+5$, i.e.\ $\delta:=j-s$
satisfies $\delta<0.2s+1$.  Since the window has width $2s$, this is
$u(j)\lesssim 1/10$.
\end{definition}

\begin{lemma}[Positivity]
If $s<j$ then $N<j^{2}$, hence $v(j)>0$.
\end{lemma}
\begin{proof}
$N<(s+1)^{2}\le j^{2}$.
\end{proof}

Writing $j=s+\delta$ we shall repeatedly use
\begin{equation}\label{eq:expand}
  v(j)=(s+\delta)^{2}-N = s^{2}+2s\delta+\delta^{2}-N \le 2s\delta+\delta^{2},
\end{equation}
which holds because $s^{2}\le N$.  Inequality~\eqref{eq:expand} is the entire engine
of Section~\ref{sec:deg}: on the left edge $\delta$ is a small multiple of $s$, so
$v$ is a small multiple of $s^{2}\le N$.

\section{Degeneracy of the exclusion criterion}\label{sec:deg}

\begin{lemma}[Core bound]\label{lem:core}
For every $N$ and every $j\in D_{1}(N)$,
\[
  25\,v(j)\ \le\ 11N+48s+16.
\]
\end{lemma}
\begin{proof}
With $\delta=j-s$ the decile condition gives $5\delta\le s+4$.  By
\eqref{eq:expand},
\[
  25v(j)\le 25(2s\delta+\delta^{2}) = 10s(5\delta)+(5\delta)^{2}
  \le 10s(s+4)+(s+4)^{2}=11s^{2}+48s+16,
\]
and $s^{2}\le N$.
\end{proof}

The leading constant $11/25=0.44$ is exactly $(1+0.2)^{2}-1$, the continuum value at
$u=0.1$.

\begin{theorem}[Scale-free degeneracy]\label{thm:scalefree}
For every modulus $N\ge 2^{16}$ and every $j\in D_{1}(N)$,
\[
  100\,v(j)\ <\ 45\,N.
\]
\end{theorem}
\begin{proof}
From $N\ge 2^{16}$ we get $s\ge 2^{8}=256$, hence $256s\le s^{2}\le N$ and, using
$N\ge 65536$, also $192s+64<N$.  Multiplying Lemma~\ref{lem:core} by $4$ gives
$100v\le 44N+192s+64<45N$.
\end{proof}

\begin{theorem}[Degeneracy at $96$ bits]\label{thm:deg96}
Let $2^{95}\le N<2^{96}$ and $j\in D_{1}(N)$.  Then $v(j)<2^{95}$.
\end{theorem}
\begin{proof}
$N\ge 2^{95}\ge 2^{16}$, so $100v<45N<45\cdot2^{96}=90\cdot 2^{95}<100\cdot 2^{95}$.
\end{proof}

\begin{corollary}[Bit drop]\label{cor:bitdrop}
\begin{enumerate}
\item If $N\ge 2^{16}$ and $j\in D_{1}(N)$ then $2v(j)<N$, hence
$\bitlen v(j)<\bitlen N$.
\item If moreover $2^{95}\le N<2^{96}$ then $\bitlen v(j)\le 95$.
\end{enumerate}
\end{corollary}
\begin{proof}
(i) $100v<45N<50N$.  Let $\beta=\bitlen N$; then $N<2^{\beta}=2\cdot 2^{\beta-1}$, so
$2v<2\cdot 2^{\beta-1}$, i.e.\ $v<2^{\beta-1}$.  (ii) is Theorem~\ref{thm:deg96}.
\end{proof}

\begin{proposition}[The size hypotheses are necessary]\label{prop:cex}
\begin{enumerate}
\item $N=36482$, $s=191$, $j=230$ lies in $D_{1}(N)$ (indeed $5\cdot 39=195<196=s+5$)
and $v(j)=16418$ while $0.45N=16416.9$; thus $45N\le 100v(j)$ and
Theorem~\ref{thm:scalefree} fails without $N\ge 2^{16}$.
\item $N=962$, $s=31$, $j=38$ lies in $D_{1}(N)$ ($5\cdot 7=35<36=s+5$) and
$v(j)=482$ while $N/2=481$; thus $N\le 2v(j)$ and even
Corollary~\ref{cor:bitdrop}(i) fails without a size hypothesis.
\end{enumerate}
An exhaustive scan indicates that $N=36482$ is the largest modulus violating
$100v<45N$ and $N=962$ the largest violating $2v<N$, so the hypothesis
$N\ge 2^{16}$ is nearly sharp for the first bound and generous for the second.
\end{proposition}

\begin{theorem}[The filtered first decile is empty]\label{thm:empty}
For $2^{95}\le N<2^{96}$,
\[
  \bigl\{\,j\in[s+1,3s] : 5(j-s)<s+5 \text{ and } v(j)\ge 2^{95}\,\bigr\}=\varnothing .
\]
\end{theorem}
\begin{proof}
Immediate from Theorem~\ref{thm:deg96}.
\end{proof}

Thus the removed fraction of first-decile mass is exactly $1$, for every $96$-bit
modulus and every dataset: the criterion carries no discriminatory information there.

\begin{theorem}[Full-size tail]\label{thm:tail}
Let $2^{95}\le N<2^{96}$ and $142s\le 100j$ (i.e.\ $u\ge 0.21$).  Then
$v(j)\ge 2^{95}$.
\end{theorem}
\begin{proof}[Proof sketch]
From $100j\ge 142s$ we get $10^{4}j^{2}\ge 20164\,s^{2}$.  Also $N\le s^{2}+2s$ and
$s\le 2^{48}$ since $N<2^{96}$.  Hence
\[
  10^{4}\bigl(j^{2}-N\bigr)\ \ge\ 20164\,s^{2}-10^{4}N\ \ge\ 10164\,N-40328\,s .
\]
Finally $40328\cdot 2^{48}\le 164\cdot 2^{95}$ and $N\ge 2^{95}$ give
$10164N-40328s\ge 10^{4}\cdot 2^{95}$.
\end{proof}

\section{Exact band geometry}\label{sec:bands}

\begin{theorem}[Strict monotonicity]\label{thm:mono}
If $s<j_{1}<j_{2}$ then $v(j_{1})<v(j_{2})$.
\end{theorem}
\begin{proof}
$j_{1}^{2}<j_{2}^{2}$ and $N<j_{1}^{2}$.
\end{proof}

\begin{theorem}[Band $=$ positional cut]\label{thm:cut}
For $T\ge 1$ and $j>s$,
\[
  v(j)<T \iff j\le\bigl\lfloor\sqrt{N+T-1}\,\bigr\rfloor .
\]
\end{theorem}
\begin{proof}
$v(j)<T\iff j^{2}\le N+T-1\iff j\le\lfloor\sqrt{N+T-1}\rfloor$, the last step being
the defining property of the integer square root.
\end{proof}

\begin{corollary}[The excluded set is a left-edge interval]\label{cor:count}
For $T\ge 1$,
\[
  \{\,j\in(s,3s]:v(j)<T\,\}=\bigl(s,\ \min(3s,\lfloor\sqrt{N+T-1}\rfloor)\bigr],
\]
so that
\begin{equation}\label{eq:card}
  \#\{\,j\in(s,3s]:v(j)<T\,\}=\min\bigl(3s,\lfloor\sqrt{N+T-1}\rfloor\bigr)-s .
\end{equation}
\end{corollary}

\begin{proposition}[How small the channel gets]\label{prop:left}
$v(s+1)\le 2s+1\le 2\sqrt N+1$.
\end{proposition}
\begin{proof}
$(s+1)^{2}=s^{2}+2s+1\le N+2s+1$.
\end{proof}

So the extreme left of the window realises residues of about half the bit-length of
$N$ --- roughly $2^{49}$ for a $96$-bit modulus.  This is the arithmetic mechanism
behind the inclusion channel: such numbers are smooth vastly more often than
full-size draws.

Let $C_{\le b}(N):=\#\{j\in(s,3s]:\bitlen v(j)\le b\}$.

\begin{theorem}[Cumulative counts]\label{thm:cum}
$C_{\le b}(N)=\min\bigl(3s,\lfloor\sqrt{N+2^{b}-1}\rfloor\bigr)-s$.
\end{theorem}
\begin{proof}
$\bitlen v\le b\iff v<2^{b}$; apply \eqref{eq:card} with $T=2^{b}$.
\end{proof}

\begin{theorem}[Telescoping band populations]\label{thm:tele}
For every $b$,
\[
  \#\{j\in(s,3s]:\bitlen v(j)=b+1\} = C_{\le b+1}(N)-C_{\le b}(N)
\]
\[
  = \min\bigl(3s,\lfloor\sqrt{N+2^{b+1}-1}\rfloor\bigr)
   -\min\bigl(3s,\lfloor\sqrt{N+2^{b}-1}\rfloor\bigr).
\]
\end{theorem}
\begin{proof}
The sets $\{\bitlen v\le b\}$ and $\{\bitlen v=b+1\}$ are disjoint with union
$\{\bitlen v\le b+1\}$; combine with Theorem~\ref{thm:cum}.
\end{proof}

\begin{remark}
The bit-length histogram of a Fermat window is a deterministic function of $N$
alone: a telescoping sequence of differences of integer square roots.  Any apparent
``band distribution'' in a hit sample is the composition of this fixed geometric
profile with the smoothness process, never an independent random object.
\end{remark}

Write $m:=\lfloor\sqrt{N+2^{95}-1}\rfloor$ for the cut point at $T=2^{95}$.

\begin{lemma}[The cut lies inside the window]\label{lem:inside}
For $2^{95}\le N<2^{96}$, $m\le 3s$.
\end{lemma}
\begin{proof}
$N+2^{95}-1\le 2N\le 2(s^{2}+2s)<(3s+1)^{2}$ for $s\ge 1$.
\end{proof}

\begin{theorem}[Lower bound]\label{thm:lower}
For $2^{95}\le N<2^{96}$ we have $m-s\ge 0.22\,s$; equivalently
$11s\le 50\,\#\{j\in(s,3s]:v(j)<2^{95}\}$.
\end{theorem}
\begin{proof}[Proof sketch]
Put $k=\lceil 1.22 s\rceil$, so $2500k^{2}\le(61s+49)^{2}=3721s^{2}+5978s+2401$.
Since $2^{95}\ge N/2$ and $s^{2}\le N$, and using $s\ge 2^{47}$ to absorb the linear
terms, $3721s^{2}+5978s+2401\le 2500(N+2^{95}-1)$; hence $k\le m$.  Combine with
\eqref{eq:card} and Lemma~\ref{lem:inside}.
\end{proof}

Since the first decile has width at most $0.2s+1$, the excluded interval contains it
with a margin of at least $0.02s$ positions --- about $2^{45}$ positions at $96$ bits.

\begin{theorem}[Upper bound on the cut]\label{thm:upper}
For $2^{95}\le N<2^{96}$, $100\,m\le 142\,s$.
\end{theorem}
\begin{proof}[Proof sketch]
With $k=\lfloor 1.42s\rfloor$ one has $142s<100(k+1)$, whence
$(k+1)^{2}>2(s^{2}+2s+1)\ge 2N\ge N+2^{95}$, so $m<k+1$.
\end{proof}

\begin{theorem}[Window fraction of the tiny channel]\label{thm:frac}
For every $96$-bit modulus,
\[
  0.11\ \le\ \frac{\#\{j\in(s,3s]:v(j)<2^{95}\}}{2s}\ \le\ 0.21 .
\]
\end{theorem}
\begin{proof}
Combine \eqref{eq:card}, Lemma~\ref{lem:inside}, Theorem~\ref{thm:lower} and
Theorem~\ref{thm:upper}.
\end{proof}

\section{The continuum crossing curve}\label{sec:cont}

In the continuum approximation $j\approx s(1+2u)$ and $s\approx\sqrt N$, so
$v\approx\bigl((1+2u)^{2}-1\bigr)N$.

\begin{definition}[Crossing position]
For $N>0$, $\displaystyle u_{0}(N):=\frac{\sqrt{1+2^{95}/N}-1}{2}$.
\end{definition}

\begin{theorem}[Exact characterisation]\label{thm:cross}
For $N>0$ and $u\ge0$,
\[
  \bigl((1+2u)^{2}-1\bigr)N\ \ge\ 2^{95} \iff u\ \ge\ u_{0}(N).
\]
\end{theorem}
\begin{proof}
The left inequality is equivalent to $(1+2u)^{2}\ge 1+2^{95}/N$, i.e.\ (both sides
being nonnegative) to $1+2u\ge\sqrt{1+2^{95}/N}$.
\end{proof}

\begin{theorem}[Monotonicity]\label{thm:anti}
If $0<N_{1}<N_{2}$ then $u_{0}(N_{2})<u_{0}(N_{1})$: larger moduli expose full-size
residues earlier in the window.
\end{theorem}

\begin{theorem}[Sharp interval]\label{thm:interval}
For $2^{95}\le N<2^{96}$,
\[
  \frac{\sqrt6-2}{4}\ <\ u_{0}(N)\ \le\ \frac{\sqrt2-1}{2},
\]
numerically $0.11237\ldots<u_{0}(N)\le 0.20711\ldots$.
\end{theorem}
\begin{proof}
$N\ge 2^{95}$ gives $2^{95}/N\le1$, so $u_{0}(N)\le(\sqrt2-1)/2$.  $N<2^{96}$ gives
$2^{95}/N>1/2$, so $u_{0}(N)>(\sqrt{3/2}-1)/2=(\sqrt6-2)/4$.
\end{proof}

\begin{corollary}[Structural cause of the degeneracy]\label{cor:tenth}
For every $N$ with $0<N<2^{96}$ we have $\tfrac1{10}<u_{0}(N)$, since $2.4<\sqrt6$
gives $(\sqrt6-2)/4>0.1$.
\end{corollary}

Thus no full-size residue can occur in the first decile of a $96$-bit modulus --- the
continuum explanation of Theorem~\ref{thm:deg96} --- and the observed left edge of the
post-filter support, $u\approx0.114$, is not an empirical accident but the value
$(\sqrt6-2)/4=0.11237\ldots$, attained in the limit at the top of the $96$-bit range.

\begin{theorem}[Phase transition in the cut-off]\label{thm:phase}
Let $c\in\mathbb R$ be a candidate positional cut-off.
\begin{enumerate}
\item If $c\le(\sqrt6-2)/4$ then for every $N\in(0,2^{96})$ and every $u\in[0,c)$ one
has $\bigl((1+2u)^{2}-1\bigr)N<2^{95}$: the criterion is degenerate for all $96$-bit
moduli.
\item If $c>(\sqrt2-1)/2$ then for every $N\ge 2^{95}$ there is $u\in[0,c)$ with
$\bigl((1+2u)^{2}-1\bigr)N\ge 2^{95}$: the criterion is informative for all $96$-bit
moduli.
\end{enumerate}
Hence the transition window is exactly $\bigl((\sqrt6-2)/4,(\sqrt2-1)/2\bigr]$, and
the experimental cut-off $c=0.1$ lies strictly inside the degenerate regime.
\end{theorem}
\begin{proof}
(1) If some $u<c\le(\sqrt6-2)/4$ satisfied the inequality, Theorem~\ref{thm:cross}
would give $u\ge u_{0}(N)>(\sqrt6-2)/4$ by Theorem~\ref{thm:interval}, a
contradiction.  (2) Take $u=(\sqrt2-1)/2\ge u_{0}(N)$ and apply
Theorem~\ref{thm:cross}.
\end{proof}

\section{Sharp discrete constants}\label{sec:sharp}

\begin{theorem}[Sharp degeneracy, $u\le0.1123$]\label{thm:sharpdeg}
Let $2^{95}\le N<2^{96}$, $j>s$, and suppose $10^{4}(j-s)\le 2246\,s$, i.e.\
$u\le0.1123$.  Then $v(j)<2^{95}$.
\end{theorem}
\begin{proof}[Proof sketch]
With $\delta=j-s$ and $10^{4}\delta\le 2246s$, expansion \eqref{eq:expand} gives
\[
  10^{8}\bigl(2s\delta+\delta^{2}\bigr)\le
  \bigl(2\cdot 2246\cdot 10^{4}+2246^{2}\bigr)s^{2}=49\,964\,516\,s^{2}\le
  49\,964\,516\,N,
\]
so $10^{8}v(j)<\tfrac12\cdot 10^{8}N$, and $N<2^{96}=2\cdot 2^{95}$ finishes.
\end{proof}

\begin{theorem}[Failure beyond $u=0.2072$]\label{thm:witness}
There exist $N$ with $2^{95}\le N<2^{96}$ and $j$ in the window with $u(j)\le0.2072$
and $v(j)\ge 2^{95}$.  An explicit witness is
\[
  N=199032864766431^{2}=39614081257132410564184477761,\qquad j=281512083925640,
\]
for which $s=199032864766431$, $u(j)=0.20720\ldots$ and
$j^{2}=79249053396156578873049409600$, so $v(j)\ge 2^{95}$.
\end{theorem}

\begin{corollary}[Bracketing]\label{cor:bracket}
Let $c^{\star}$ be the supremum of cut-offs $c$ for which
``$u(j)\le c\Rightarrow v(j)<2^{95}$'' holds for all $96$-bit moduli.  Then
$0.1123\le c^{\star}\le 0.2072$, matching the continuum endpoints
$(\sqrt6-2)/4=0.11237\ldots$ and $(\sqrt2-1)/2=0.20711\ldots$ to four decimals.
\end{corollary}

\section{Discrete--continuum bridge}\label{sec:bridge}

\begin{theorem}[Count bridge]\label{thm:countbridge}
For every $N\ge1$, with $m=\lfloor\sqrt{N+2^{95}-1}\rfloor$ and $s=\lfloor\sqrt
N\rfloor$,
\[
  \Bigl|(m-s)-\bigl(\sqrt{N+2^{95}}-\sqrt N\bigr)\Bigr|\ \le\ 2 .
\]
\end{theorem}
\begin{proof}[Proof sketch]
$m\le\sqrt{N+2^{95}-1}<m+1$ and $s\le\sqrt N<s+1$, together with
$\sqrt x\le\sqrt{x-1}+1$ for $x\ge1$.  Each comparison costs at most $1$; the bound
follows after cancellation.
\end{proof}

\begin{theorem}[Fraction bridge]\label{thm:fracbridge}
For $N\ge 2^{95}$,
\[
  \left|\frac{m-s}{2s}-u_{0}(N)\right|\ \le\ \frac{3}{s}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Write $A=\sqrt N$, $B=\sqrt{N+2^{95}}$, so $u_{0}(N)=(B-A)/(2A)$.  Then
\[
  \frac{m-s}{2s}-\frac{B-A}{2A}
  = \frac{(m-s)-(B-A)}{2s}+\frac{(B-A)(A-s)}{2sA}.
\]
The first term is at most $1/s$ by Theorem~\ref{thm:countbridge}; for the second,
$0\le A-s<1$ and $B-A\le A$ (since $2^{95}\le N$ implies $B\le 2A$), giving another
$1/s$.
\end{proof}

\begin{remark}
For a $96$-bit modulus $s\ge 2^{47}\approx 1.4\times10^{14}$, so
$3/s\approx 2\times10^{-14}$: the discrete and continuum excluded fractions coincide
to about fourteen decimal digits.  Discretisation can never account for a discrepancy
in a fitted edge weight.
\end{remark}

\section{Position and bit-length are two stratifications}\label{sec:two}

Within a single modulus, Theorem~\ref{thm:mono} says the bit-length band is a
strictly increasing function of the position: the two stratifications coincide.
Across moduli they do not, and the failure occurs well inside the window.

\begin{theorem}[Full-size witness at $u=0.15$]\label{thm:w1}
Let $N_{1}=(2^{48}-1)^{2}=79228162514263774643590529025$ and
$j_{1}=365917469723851$.  Then $2^{95}\le N_{1}<2^{96}$, $s_{1}=2^{48}-1$, $j_{1}$ is
in the window, $u(j_{1})\le 0.15$, and
\[
  v(j_{1})=54667432134841638586607741176\ \ge\ 2^{95}=39614081257132168796771975168 .
\]
\end{theorem}

\begin{theorem}[Tiny witness at $u=0.20$]\label{thm:w2}
Let $N_{2}=199032864766431^{2}=39614081257132410564184477761$ and
$j_{2}=278646010673003$.  Then $2^{95}\le N_{2}<2^{96}$, $s_{2}=199032864766431$,
$j_{2}$ is in the window, $u(j_{2})=0.2\ge 0.15$, and
\[
  v(j_{2})=38029518006846891224808560248\ <\ 2^{95}.
\]
\end{theorem}

Both are verified by direct integer arithmetic:
$j_{1}^{2}=133895594649105413230198270201$ and
$j_{2}^{2}=77643599263979301788993038009$.

\begin{corollary}[No universal positional surrogate]
There is no cut-off $c\in[0.15,0.20]$ such that, uniformly over $96$-bit moduli,
``$u\le c$'' is equivalent to ``$v<2^{95}$'': modulus $N_{1}$ violates the forward
implication at $u=0.15$, and modulus $N_{2}$ violates the converse at $u=0.20$.
\end{corollary}

The witnesses are the extremal moduli predicted by Theorem~\ref{thm:interval}:
$N_{1}$ sits just below $2^{96}$, where $u_{0}\approx0.11237$, so full-size residues
begin early; $N_{2}$ sits just above $2^{95}$, where $u_{0}\approx0.20711$, so tiny
residues persist late.

\begin{theorem}[Synthesis: the spike is not one object]\label{thm:synth}
For $96$-bit moduli the window decomposes into
\begin{enumerate}
\item a \emph{provably tiny prefix}: every first-decile position has
$\bitlen v\le 95$ (Theorem~\ref{thm:deg96});
\item a \emph{provably full-size tail}: every position with $u\ge0.21$ has
$\bitlen v\ge 96$ (Theorem~\ref{thm:tail});
\item a \emph{modulus-dependent middle}: both behaviours occur at the same normalised
position for different moduli (Theorems~\ref{thm:w1}--\ref{thm:w2}).
\end{enumerate}
Consequently the position statistic and the bit-length band are independent
stratifications of the window across the modulus ensemble, and a ``$v\ge2^{95}$'' cut
is a geometric operation on the left edge, not a data-driven one.
\end{theorem}

\section{Algorithms}

\subsection{Exact band histogram}
Given $N$ and a maximal bit-length $B$, Theorems~\ref{thm:cum}--\ref{thm:tele} give
the exact vector of band populations by evaluating
$C_{\le b}=\min(3s,\lfloor\sqrt{N+2^{b}-1}\rfloor)-s$ for $b\le B$ and differencing.
The cost is $B$ integer square roots of $O(\log N)$-bit numbers, replacing an
$O(s)$ scan over $2s\approx 2^{48}$ positions, and the answer is exact.

\subsection{Degeneracy audit of an exclusion criterion}
Given $N$, a residue threshold $T$ and a positional cut-off $c$, compute
$m=\min(3s,\lfloor\sqrt{N+T-1}\rfloor)$ and $p=s+\lfloor 2sc\rfloor$.  The fraction of
the region $\{u\le c\}$ removed by the filter $v\ge T$ is
$(\min(m,p)-s)/(p-s)$, and it equals $1$ exactly when $p\le m$.  This is the test
that Theorem~\ref{thm:empty} shows returns $1$ for $T=2^{95}$, $c=0.1$ and every
$96$-bit $N$.  Cost: one integer square root.

\subsection{Crossing-curve bracket for an ensemble}
For $N$ ranging over $[2^{\beta-1},2^{\beta})$ and threshold $T$,
Theorems~\ref{thm:anti}--\ref{thm:interval} give the range of the crossing curve as
\[
  \Bigl(\tfrac{\sqrt{1+T/2^{\beta}}-1}{2},\ \tfrac{\sqrt{1+T/2^{\beta-1}}-1}{2}\Bigr].
\]
For $T=2^{\beta-1}$ this is exactly $\bigl((\sqrt6-2)/4,(\sqrt2-1)/2\bigr]$,
independent of $\beta$: the interval is a universal constant of the construction.

\section{Consequences for empirical studies}

\emph{(a) The reported control was uninformative in the region it targeted.}  The
``keep $v\ge2^{95}$'' clause removes $100\%$ of first-decile mass by
Theorem~\ref{thm:empty}, so it cannot discriminate a magnitude artifact from genuine
structure there.  The empirical band table agrees to the digit: zero of the $7221$
full-size hits and zero of the $426525$ full-size controls lie in the first decile.

\emph{(b) The surviving signal is real but relocated.}  Refitting on the full-size
subpopulation yields edge weight $0.0403$ with interval $[0.0301,0.0525]$, measured at
the surviving population's own support edge $u\approx0.11$, which
Corollary~\ref{cor:tenth} identifies as $(\sqrt6-2)/4$ rather than a data-dependent
quantity.  The honest reading of $0.0794\to0.0403$ is a split: roughly half the
original weight is a tiny-residue inclusion channel (residues as small as
$2\sqrt N\approx 2^{50}$ by Proposition~\ref{prop:left}), and roughly half is an
excess among full-size residues not explained by magnitude.

\emph{(c) Band mass is geometry, not statistics.}  Observed hit mass by band ($0$
below $80$ bits, $0.0089$ in $80$--$89$, $0.2385$ in $90$--$95$, $0.7527$ at $\ge96$)
should be read against the deterministic profile of Theorem~\ref{thm:tele}.

\emph{(d) Any positional-shape model needs two indices.}  By
Theorem~\ref{thm:synth}, a model indexed by $u$ alone absorbs an uncontrolled
mixture of magnitude effects at the left edge; the fix is to stratify by
$\bitlen v$, which is cheap and exact.

\emph{(e) Discretisation is not an available excuse}, by
Theorem~\ref{thm:fracbridge}.

\section{Discussion}

The quantity being controlled for --- residue magnitude --- and the quantity being
measured --- position in the window --- are not independent variables but, within each
modulus, the same variable in two coordinates, related by the strictly increasing map
$j\mapsto j^{2}-N$.  A control conditioning on one while measuring the other is not a
weak control; it is an empty one on the region of interest.

What makes the situation recoverable is that the coupling is exactly computable: the
band structure is a telescoping sequence of integer square roots, the crossing point
is an explicit algebraic function of $N$, and across a bit-level ensemble that
function sweeps a fixed interval bounded by two quadratic irrationalities.

Three limitations should be stated plainly.  First, the theorems concern the geometry
of the window, not the smoothness process; the persistence of an edge component among
full-size residues is an empirical statement supported by the refit, not a theorem.
Second, the empirical numbers come from one experimental design --- a fifty-bin Poisson
fit with a half-Gaussian edge component and a bootstrap clustered over moduli --- and
amplitudes from a differently parametrised fit are not numerically comparable; the
internal comparison $0.0794\to0.0403$ is the meaningful one.  Third, the reference
population was a capped set of non-hit positions per modulus, which is
position-uniform rather than smoothness-matched.

Within those limits the mathematical conclusion is unconditional: the left-edge spike
of a Fermat window is not a single object, and no positional statistic can be
interpreted without simultaneously fixing the bit-length band.

\section{Future directions}

\subsection{Sharpening what is already here}
\begin{itemize}
\item \emph{Determine $c^{\star}$ exactly.}  Corollary~\ref{cor:bracket} brackets the
universal discrete degeneracy constant in $[0.1123,0.2072]$; feeding
Theorem~\ref{thm:fracbridge} back into the argument should show the discrete constant
equals the continuum infimum up to $O(1/s)$.
\item \emph{General thresholds and windows.}  The proofs use only $s^{2}\le N$ and the
window width, so the natural generalisation is a two-parameter family indexed by
$T/N$ and the window multiplier, in which
$\bigl((\sqrt6-2)/4,(\sqrt2-1)/2\bigr]$ is one fibre.
\item \emph{Second-order band profile.}  Expanding the integer square roots
asymptotically should yield the band profile as a smooth density in $u$ plus an
explicitly bounded lattice error --- the exact geometric null against which observed
band masses ought to be normalised.
\end{itemize}

\subsection{Testable conjectures about the surviving signal}
\begin{itemize}
\item \emph{The residual edge excess should scale.}  If the full-size edge component
with weight $\approx0.04$ is real, its magnitude should vary predictably with modulus
bit-length and smoothness bound; a scan at $80$ and $112$ bits with the same design
would exhibit the predicted drift or refute the effect.
\item \emph{Band-stratified refit.}  Fitting an edge weight separately in each band
($90$--$95$, $\ge96$) should show monotone decay with band index if the effect is
magnitude-driven and a flat profile if it is genuinely positional.
\item \emph{Crossing-curve stratification.}  Since $u_{0}(N)$ is strictly decreasing,
one may run the analysis in the rescaled coordinate $u/u_{0}(N)$, in which the
tiny/full-size boundary is at $1$ for every modulus; residual structure surviving that
reparametrisation is free of the magnitude channel by construction.
\end{itemize}

